<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit("CLI only\n");}
$configFile=__DIR__.'/../../config/config.local.php';if(!is_file($configFile))exit("Configure config/config.local.php first.\n");$c=require $configFile;$db=new PDO($c['dsn'],$c['db_user'],$c['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
if(($argv[1]??'')!=='--development-only')exit("This inserts fictional academic demo accounts/data. Run: php database/seeders/demo.php --development-only\n");
$roles=[];foreach($db->query('SELECT id,name FROM roles') as $r)$roles[$r['name']]=$r['id'];
foreach(['Basketball','Soccer','Volleyball','Track and Field','Swimming'] as $sport)$db->prepare('INSERT IGNORE INTO sports(name) VALUES(?)')->execute([$sport]);$sportIds=$db->query('SELECT id FROM sports ORDER BY id')->fetchAll(PDO::FETCH_COLUMN);
$accounts=[];foreach([['Demo Administrator','admin'],['Demo Clinician','clinician'],['Demo Coach','coach']] as [$name,$role]){$email=$role.'@demo.invalid';$db->prepare('INSERT INTO users(role_id,full_name,email,password_hash) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)')->execute([$roles[$role],$name,$email,password_hash('Demo-Only-Change-Me-2030!',PASSWORD_DEFAULT)]);$accounts[$role]=(int)$db->lastInsertId();}
$db->prepare('INSERT INTO teams(sport_id,name,coach_user_id) VALUES(?,?,?)')->execute([$sportIds[0],'Demo Falcons',$accounts['coach']]);$team=(int)$db->lastInsertId();
$clin=$accounts['clinician'];for($i=1;$i<=100;$i++){$name=sprintf('Fictional Athlete %03d',$i);$email=sprintf('athlete%03d@demo.invalid',$i);$db->prepare('INSERT INTO users(role_id,full_name,email,password_hash) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)')->execute([$roles['athlete'],$name,$email,password_hash('Demo-Only-Change-Me-2030!',PASSWORD_DEFAULT)]);$uid=(int)$db->lastInsertId();$db->prepare('INSERT IGNORE INTO athlete_profiles(user_id,student_id,sport_id,department) VALUES(?,?,?,?)')->execute([$uid,sprintf('DEMO-%04d',$i),$sportIds[($i-1)%count($sportIds)],'Fictional Demonstration']);$db->prepare('INSERT IGNORE INTO team_memberships(team_id,athlete_user_id,start_date) VALUES(?,?,CURDATE())')->execute([$team,$uid]);$summary='Fictional recovery concern '.$i;$db->prepare('INSERT INTO recovery_cases(athlete_user_id,assigned_clinician_id,summary,concern,status) VALUES(?,?,?,?,?)')->execute([$uid,$clin,$summary,'Simulated academic workflow record; contains no real health information.', ['submitted','under_review','monitoring','closed'][($i-1)%4]]);$cid=(int)$db->lastInsertId();if($i%2===0)$db->prepare('INSERT INTO recovery_milestones(case_id,label,status,note,recorded_by) VALUES(?,?,?,?,?)')->execute([$cid,'Documentation item received','documented','Fictional sample record',$clin]);if($i%3===0)$db->prepare('INSERT INTO follow_up_appointments(case_id,scheduled_at,purpose,created_by) VALUES(?,?,?,?)')->execute([$cid,date('Y-m-d H:i:s',strtotime('+'.($i%20).' days')),'Fictional follow-up entry',$clin]);$db->prepare('INSERT INTO activity_logs(user_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)')->execute([$accounts['admin'],'demo_seeded','case',$cid,'Fictional development seed event']);}
echo "Seeded 100 fictional athlete profiles and cases plus demo staff accounts. Password for all demo accounts: Demo-Only-Change-Me-2030! Change before any shared demo; never use in production.\n";
